"""Score transcripts vs the user-supplied partial reference (verse1 + pre-chorus + chorus1)."""
import json, re, sys, unicodedata, glob, os
import jiwer

REF = {
 "intro": "בא לי איזה לאב סונג, בייבי (אה)\nבסוף כל השירים אותו דבר",
 "verse1": "תדע, זה פשע, מישהו צריך להתערב\nכל יום בתשע אתה רואה לי את הלב\nמפחיד להתאהב, אוהב שזה כואב\nאיי-איי-איי-איי",
 "prechorus": "מאמי, תיראה מה נהיה ממני\nקנאית ,אובססיבית, ללא תקנה\nבחוץ הם כולם מחזיקים ממני ואני מחזיקה מעצמי ילדה\nשרק רוצה להתקשר, להיות שלך, להיקשר\nשלא כמו שיר שוב ניגמר",
 "chorus": "לא בא לי איזה לאב סונג, בייבי\nבסוף כל השירים אותו דבר\nמה יש כבר לחפש פה? שתה אספרסו\nנסגור חשבון ובוא נשרוף את העולם",
}
# section windows (seconds, by word start); derived from the vocal-stem energy + prod LRC
WIN = {"verse1": (49.0, 71.5), "prechorus": (71.5, 86.8), "chorus": (86.8, 103.8)}
GAPS = {"gap_12_34": (11.9, 33.9), "gap_49_63": (49.3, 63.2)}
EN = {"love": "לאב", "song": "סונג", "baby": "בייבי"}
FINALS = str.maketrans("ךםןףץ", "כמנפצ")

def norm(t, skel=False):
    t = re.sub(r"\([^)]*\)", " ", t)                      # ad-libs in parens
    t = t.replace("־", " ").replace("-", " ").replace("–", " ").replace("—", " ")
    t = "".join(c for c in unicodedata.normalize("NFD", t) if not ("֑" <= c <= "ׇ"))  # niqqud/te'amim
    t = t.replace("׳", "").replace("״", "").replace("'", "").replace("’", "").replace('"', "")
    t = "".join(" " if unicodedata.category(c)[0] in "PS" else c for c in t)
    t = t.lower()
    t = " ".join(EN.get(w, w) for w in t.split())
    t = t.translate(FINALS)
    if skel:  # ktiv male/haser-agnostic: drop matres lectionis vav/yod
        t = t.replace("ו", "").replace("י", "")
        t = " ".join(w for w in t.split() if w)
    return " ".join(t.split())

def score(ref, hyp):
    r, h = norm(ref), norm(hyp)
    rs, hs = norm(ref, True), norm(hyp, True)
    if not h:
        return {"wer": 1.0, "cer": 1.0, "cer_skel": 1.0}
    return {"wer": round(jiwer.wer(r, h), 3), "cer": round(jiwer.cer(r, h), 3),
            "cer_skel": round(jiwer.cer(rs, hs), 3)}

def words_whisper(d):
    return [(w["start"], w["word"]) for s in d["segments"] for w in s.get("words", [])]

def words_gemini(text):
    out = []
    for line in text.splitlines():
        m = re.match(r"\s*\[(\d+):(\d+)\]\s*(.*)", line)
        if not m or "(spoken)" in line:
            continue
        t = int(m[1]) * 60 + int(m[2])
        out += [(t + 0.0, w) for w in m[3].split()]
    return out

def text_in(ws, lo, hi):
    return " ".join(w.strip() for t, w in ws if lo <= t < hi)

rows = []
for f in sorted(g for g in glob.glob("/tmp/karaoke-he-bench/results/*.json") if "clip_" not in g and "scores" not in g):
    d = json.load(open(f))
    if "segments" in d:
        ws = words_whisper(d); rt = d["transcribe_s"]
    elif "text" in d:
        ws = words_gemini(d["text"]); rt = d["elapsed_s"]
    else:
        continue
    lab = os.path.basename(f)[:-5]
    full_ref = "\n".join(REF[k] for k in WIN)
    full_hyp = text_in(ws, WIN["verse1"][0], WIN["chorus"][1])
    row = {"label": lab, "runtime_s": rt, "all": score(full_ref, full_hyp)}
    for k, (lo, hi) in WIN.items():
        row[k] = score(REF[k], text_in(ws, lo, hi))
    for k, (lo, hi) in GAPS.items():
        row[k] = len([1 for t, w in ws if lo <= t < hi])
    row["hyp_window"] = full_hyp
    rows.append(row)

json.dump(rows, open("/tmp/karaoke-he-bench/results/scores.json", "w"), ensure_ascii=False, indent=1)
print(f"{'label':32} {'rt':>6} | {'WER':>5} {'CER':>5} {'CERsk':>5} | v1 CER | pre CER | ch CER | w12-34 w49-63")
for r in rows:
    a = r["all"]
    print(f"{r['label']:32} {r['runtime_s']:6} | {a['wer']:5} {a['cer']:5} {a['cer_skel']:5} | {r['verse1']['cer']:6} | {r['prechorus']['cer']:7} | {r['chorus']['cer']:6} | {r['gap_12_34']:6} {r['gap_49_63']:6}")
if "-v" in sys.argv:
    print("\nREF:", norm("\n".join(REF[k] for k in WIN)))
    for r in rows:
        print(f"\n[{r['label']}]", norm(r["hyp_window"]))

