uv run python - <<'EOF'
import json, re, httpx
jobs=json.load(open("bench/out/jobs-0.41.0.json"))
W=re.compile(r"<(\d{1,2}):(\d{2})(?:[.:](\d{1,3}))?>")
def sec(m): f=m[3] or "0"; return int(m[1])*60+int(m[2])+int(f)/10**len(f)
for sid,j in jobs.items():
    r=httpx.get(j["share"]+"/lyrics.lrc",timeout=20)
    if r.status_code!=200: continue
    hits=[]
    for ln in r.text.splitlines():
        ts=[sec(m) for m in W.finditer(ln)]
        gaps=[b-a for a,b in zip(ts,ts[1:])]
        if any(g>4 for g in gaps): hits.append((ln[:10], round(max(gaps),1)))
    if hits: print(sid, len(hits), hits[:4])
EOF

